CREATE TYPE "incident_severity" AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL'); CREATE TYPE "incident_status" AS ENUM ('OPEN','CLOSED');
CREATE TABLE "student_incidents" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"enrollment_id" UUID NOT NULL,"occurred_at" TIMESTAMPTZ(3) NOT NULL,"category" TEXT NOT NULL,"severity" "incident_severity" NOT NULL,"description" TEXT NOT NULL,"status" "incident_status" NOT NULL DEFAULT 'OPEN',"closed_at" TIMESTAMPTZ(3),"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "student_incidents_pkey" PRIMARY KEY("id"),CONSTRAINT "student_incidents_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE CASCADE,CONSTRAINT "student_incidents_enrollment_id_fkey" FOREIGN KEY("enrollment_id") REFERENCES "enrollments"("id") ON DELETE RESTRICT);
CREATE TABLE "disciplinary_actions" ("id" UUID NOT NULL DEFAULT uuidv7(),"incident_id" UUID NOT NULL,"type" TEXT NOT NULL,"description" TEXT NOT NULL,"starts_at" DATE NOT NULL,"ends_at" DATE,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "disciplinary_actions_pkey" PRIMARY KEY("id"),CONSTRAINT "disciplinary_actions_dates_valid" CHECK(ends_at IS NULL OR ends_at>=starts_at),CONSTRAINT "disciplinary_actions_incident_id_fkey" FOREIGN KEY("incident_id") REFERENCES "student_incidents"("id") ON DELETE CASCADE);
CREATE TABLE "health_visits" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"enrollment_id" UUID NOT NULL,"visited_at" TIMESTAMPTZ(3) NOT NULL,"symptoms" TEXT NOT NULL,"action_taken" TEXT NOT NULL,"guardian_notified" BOOLEAN NOT NULL DEFAULT false,"follow_up_at" TIMESTAMPTZ(3),"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "health_visits_pkey" PRIMARY KEY("id"),CONSTRAINT "health_visits_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE CASCADE,CONSTRAINT "health_visits_enrollment_id_fkey" FOREIGN KEY("enrollment_id") REFERENCES "enrollments"("id") ON DELETE RESTRICT);
CREATE INDEX "student_incidents_school_id_status_occurred_at_idx" ON "student_incidents"("school_id","status","occurred_at" DESC); CREATE INDEX "student_incidents_enrollment_id_occurred_at_idx" ON "student_incidents"("enrollment_id","occurred_at" DESC); CREATE INDEX "disciplinary_actions_incident_id_idx" ON "disciplinary_actions"("incident_id"); CREATE INDEX "health_visits_school_id_visited_at_idx" ON "health_visits"("school_id","visited_at" DESC); CREATE INDEX "health_visits_enrollment_id_visited_at_idx" ON "health_visits"("enrollment_id","visited_at" DESC);
CREATE TRIGGER trg_student_incidents_updated_at BEFORE UPDATE ON "student_incidents" FOR EACH ROW EXECUTE FUNCTION set_updated_at(); CREATE TRIGGER trg_health_visits_updated_at BEFORE UPDATE ON "health_visits" FOR EACH ROW EXECUTE FUNCTION set_updated_at(); ALTER TABLE "student_incidents" ENABLE ROW LEVEL SECURITY; ALTER TABLE "health_visits" ENABLE ROW LEVEL SECURITY; CREATE POLICY school_isolation ON "student_incidents" USING(current_school_id() IS NULL OR school_id=current_school_id()) WITH CHECK(current_school_id() IS NULL OR school_id=current_school_id()); CREATE POLICY school_isolation ON "health_visits" USING(current_school_id() IS NULL OR school_id=current_school_id()) WITH CHECK(current_school_id() IS NULL OR school_id=current_school_id());
